#include "../test_tone_frequency_plan.hpp"
#include "../band_lookup.hpp"
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <limits>
static void ok(bool v,const char*s){if(!v){std::cerr<<s<<'\n';std::exit(1);}}
int main(){BandLookup l;for(auto&e:l.canonical_wspr_band_catalog()){ParsedTestToneRequest r{TestToneRequestSource::WsprBand,e.band,{}};auto p=plan_explicit_test_tone_frequency(r,1500);ok(p&&p.plan->actual_rf_frequency_hz==e.dial_frequency_hz+1500,"band");} ParsedTestToneRequest a{TestToneRequestSource::WsprBand,"20m",{}};ok(plan_explicit_test_tone_frequency(a,0).plan->actual_rf_frequency_hz==14095600,"zero offset");ok(plan_explicit_test_tone_frequency(a,1500).plan->actual_rf_frequency_hz==14097100,"default offset");ok(plan_explicit_test_tone_frequency(a,2750).plan->actual_rf_frequency_hz==14098350,"non-default offset");ParsedTestToneRequest c{TestToneRequestSource::CustomRf,"",14097123};auto q=plan_explicit_test_tone_frequency(c,1500);ok(q&&!q.plan->dial_frequency_hz&&!q.plan->audio_offset_hz&&q.plan->band=="20m","custom");for(double x:{std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity(),-std::numeric_limits<double>::infinity(),-1.0,1.5,std::ldexp(1.0,64)})ok(!plan_explicit_test_tone_frequency(a,x),"invalid offset");const double immediately_below_uint64=std::nextafter(std::ldexp(1.0,64),0.0);ok(!plan_explicit_test_tone_frequency(a,immediately_below_uint64),"largest representable convertible offset overflows dial addition");const double large_safe_offset=std::ldexp(1.0,64)-std::ldexp(1.0,24);auto large_safe=plan_explicit_test_tone_frequency(a,large_safe_offset);ok(large_safe&&large_safe.plan->audio_offset_hz.has_value()&&*large_safe.plan->audio_offset_hz==static_cast<std::uint64_t>(large_safe_offset),"large convertible safe offset");ok(!plan_explicit_test_tone_frequency({TestToneRequestSource::LegacyDefault,{},{}},0),"legacy");std::cout<<"test tone frequency plan passed\n";}
